'use strict';

// MODULES //

var setReadOnly = require( '@stdlib/utils/define-nonenumerable-read-only-property' );
var isCollection = require( '@stdlib/assert/is-collection' );
var resolveGetter = require( '@stdlib/array/base/resolve-getter' );
var iteratorSymbol = require( '@stdlib/symbol/iterator' );
var format = require( '@stdlib/string/format' );


// MAIN //

/**
* Returns an iterator which iterates over the Cartesian product of two array-like objects.
*
* ## Notes
*
* -   The order of the returned tuples follows the order of iteration of the provided array-like objects, with elements of the second array-like object varying fastest.
* -   If provided one or more empty array-like objects, the returned iterator is empty.
* -   If an environment supports `Symbol.iterator`, the returned iterator is iterable.
*
* @param {Collection} x1 - first input array
* @param {Collection} x2 - second input array
* @throws {TypeError} first argument must be an array-like object
* @throws {TypeError} second argument must be an array-like object
* @returns {Iterator} iterator
*
* @example
* var iter = iterCartesianProduct( [ 1, 2, 3 ], [ 4, 5 ] );
*
* var v = iter.next().value;
* // returns [ 1, 4 ]
*
* v = iter.next().value;
* // returns [ 1, 5 ]
*
* v = iter.next().value;
* // returns [ 2, 4 ]
*
* // ...
*/
function iterCartesianProduct( x1, x2 ) {
	var get1;
	var get2;
	var iter;
	var FLG;
	var M;
	var N;
	var i;
	var j;

	if ( !isCollection( x1 ) ) {
		throw new TypeError( format( 'invalid argument. First argument must be an array-like object. Value: `%s`.', x1 ) );
	}
	if ( !isCollection( x2 ) ) {
		throw new TypeError( format( 'invalid argument. Second argument must be an array-like object. Value: `%s`.', x2 ) );
	}
	get1 = resolveGetter( x1 );
	get2 = resolveGetter( x2 );
	M = x1.length;
	N = x2.length;
	i = 0;
	j = 0;

	// Create an iterator protocol-compliant object:
	iter = {};
	setReadOnly( iter, 'next', next );
	setReadOnly( iter, 'return', end );

	// If an environment supports `Symbol.iterator`, make the iterator iterable:
	if ( iteratorSymbol ) {
		setReadOnly( iter, iteratorSymbol, factory );
	}
	return iter;

	/**
	* Returns an iterator protocol-compliant object containing the next iterated value.
	*
	* @private
	* @returns {Object} iterator protocol-compliant object
	*/
	function next() {
		var v;
		if ( FLG || N === 0 || i >= M ) {
			return {
				'done': true
			};
		}
		v = [ get1( x1, i ), get2( x2, j ) ];

		// Update the indices for the next iteration:
		j += 1;
		if ( j >= N ) {
			j = 0;
			i += 1;
		}
		return {
			'value': v,
			'done': false
		};
	}

	/**
	* Finishes an iterator.
	*
	* @private
	* @param {*} [value] - value to return
	* @returns {Object} iterator protocol-compliant object
	*/
	function end( value ) {
		FLG = true;
		if ( arguments.length ) {
			return {
				'value': value,
				'done': true
			};
		}
		return {
			'done': true
		};
	}

	/**
	* Returns a new iterator.
	*
	* @private
	* @returns {Iterator} iterator
	*/
	function factory() {
		return iterCartesianProduct( x1, x2 );
	}
}


// EXPORTS //

module.exports = iterCartesianProduct;
